INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "お！\nあそこに困ってそうな人発見！", "春咲 ひより", 1001, 0, "ねぇねぇ、騎士クン\n手伝ってあげようよ～", 0, 2, 0, 0, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "大切な人を\n守れるようになりたい…って", "草野 優衣", 1002, 0, "わ、わたし、\nなに言ってるんだろ\nあはは…", 0, 2, 0, 0, "みんなみたいに\nわたしも強くならなきゃ", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "キミに必要な集中力と感性が", "士条 怜", 1003, 0, "少しは磨かれると思いますよ。", 0, 2, 0, 0, "フェンシングを始めてみては？", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "今日はなにして遊ぶ？", "穂高 みそぎ", 1004, 0, "みそぎはねぇ、\nかくれんぼやりたい！", 0, 2, 0, 0, "ねぇ、にいちゃん！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ねぇ…", "風宮 あかり", 1006, 0, "私といっしょに…\nいかない？", 0, 2, 0, 0, "風宮あかりです", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "プリンたべたいのー", "出雲 宮子", 1007, 0, "食べ物の恨みは怖いのー", 0, 2, 0, 0, "出雲宮子なのー", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "キミもボクの美貌に\n吸い寄せられたんだね。", "虹村 雪", 1008, 0, "いいよ。\n見られることは運命さ…", 0, 2, 0, 0, "ボクは虹村雪。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", "柊杏奈", 1009, 0, "人呼んで「疾風の冥姫」!!", 0, 2, 0, 0, "フッ…聞いて後悔するがいい！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", "姫宮 真歩", 1010, 0, "ほんまおおきにやわ～♪", 0, 2, 0, 0, "マホマホ王国のプリンセス、\nまほ姫どす", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "生き別れたお兄ちゃんを探して\n三千世界！", "衣之咲 璃乃", 1011, 0, "ここで会ったが\n100年目～！", 0, 2, 0, 0, "衣之咲璃乃です！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ち、超能力って…\n何のことかな～？", "柏崎 初音", 1012, 0, "…って、お願い！\n誰にも言わないでおいて～！", 0, 2, 0, 0, "私はハツネ、\n結構強いんだよ。\nきらーん☆", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "一応カリスマ読モJKやってまっす！", "美波 鈴奈", 1016, 0, "ヒデサイまぢ\nGF（グッドフィーリング）～♪", 0, 2, 0, 0, "ちょす！\n美波鈴奈だよ～♪", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "東京は遊園地みたいなところさー", "喜屋武 香織", 1017, 0, "でも、沖縄もとってもいいとこさー", 0, 2, 0, 0, "はいたーい。\n喜屋武香織さー。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "先生って呼ばれるのは\nくすぐったいから", "支倉 伊緒", 1018, 0, "イオちゃんって呼んでね。", 0, 2, 0, 0, "支倉伊緒です。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "あ！/\お兄ちゃ～ん\nまってよ～", "茜 ミミ", 1020, 0, "ミミをおいてかないでぇ～", 0, 2, 0, 0, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "あの……\nふぇ……", "栗林 くるみ", 1021, 0, "ふぇぇぇぇぇん……", 0, 2, 0, 0, "あ…あの…えっと…\n栗…林…くるみ…です……", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "こんな私に貴重な時間を\n割いていただき、", "風宮 より", 1022, 0, "なんてありがとうございます！", 0, 2, 0, 0, "風宮よりです。\nあああああ！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "おにいちゃんどこいくの？\nえ？", "北条 綾音", 1023, 0, "私こっち行きたいー\nね、早く早くー", 0, 2, 0, 0, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ふ、不束者ですが\nどうぞ末永く…って、", "天野 すずめ", 1025, 0, "これて何か違う…\nあああすみません！", 0, 2, 0, 0, "わっ…わっ…私、\n天野すずめといいます！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "あなたは…運命の……\n伴侶……", "倉石 恵理子", 1027, 0, "離しませんわ………\n絶対に…!!", 0, 2, 0, 0, "……クスクス…私は\n…倉石恵理子……", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", "佐々木 咲恋", 1028, 0, "…そうでしょ？？", 0, 2, 0, 0, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ぇっと…\nキミ、私のこと知らないの?!", "桜井 望", 1029, 0, "あはは、\n私もまだまだだなぁ～", 0, 2, 0, 0, "桜井望だよ！\nよろしくねっ", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "初めまして、\n私はニノン・ジュベール申すデス！", "ニノン・ジュベール", 1030, 0, "ショーグン、\nワタシと一緒に天下統一デース！", 0, 2, 0, 0, "デケデケデンっ！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "でもって私の隣にいるのが……\nえ、見えない？", "上喜 しのぶ", 1031, 0, "おかしいですね……", 0, 2, 0, 0, "上喜しのぶです。\n手元のドクロが父です。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "けんども\nそれには足りないモンが…", "野戸まひる", 1033, 0, "そう、\nオラのボケに突っ込める相方が…！", 0, 2, 0, 0, "目指すはビッグな\nお笑い芸人だっぺ！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ちょっと緊張しちゃって…", "綾瀬 ゆかり", 1034, 0, "ちょ\nちょっと一杯飲んできます…！", 0, 2, 0, 0, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "知らない人とは話しちゃいけないので", "氷川 鏡華", 1036, 0, "これ以上お話しすることは…\nないです！", 0, 2, 0, 0, "氷川鏡華…です", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "……あ、アラーム。", "柏崎 栞", 1038, 0, "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 0, 2, 0, 0, "柏崎…栞です。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "私、一人も友達がいなくて……", "双葉 碧", 1040, 0, "野に咲く花が、\n唯一の話相手です。", 0, 2, 0, 0, "ふ、双葉碧です。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", "三角 千歌", 1042, 0, "そう思っています。", 0, 2, 0, 0, "三角千歌です。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "あぁ？\nお前のそいつの仲間か？", "安芸 真琴", 1043, 0, "う、疑ってすまなかったな…", 0, 2, 0, 0, "安芸真琴だ。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "生けとし生ける全ての者よ！", "イリヤ・オーンスタイン", 1044, 0, "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 0, 2, 0, 0, "わらわこそは夜を総べる者！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "ぐふふふふ……はっ！", "遠見 空花", 1045, 0, "ｌク、クウカに何かご用ですか!?", 0, 2, 0, 0, "そこで騎士は妖精を乱暴に……", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "自由気ままで♪\n寝て遊んで、食べてケンカして…", "宮坂たまき", 1046, 0, "う～ん…\n猫ってホントに最高にゃ～♪", 0, 2, 0, 0, "宮坂たまきにゃ♪\n猫はいいにゃよ？", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "それでは早速クエストに…", "大神 美冬", 1048, 0, "…と思ったら\nバイトの時間だ！\nまたあとでね！", 0, 2, 0, 0, "大神美冬よ！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "クエストもバトルも\n掃除も洗濯も", "星野静流", 1049, 0, "お姉ちゃんがぜ～んぶ\nやってあげるからね！", 0, 2, 0, 0, "星野静流だよ！", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "見ての通りの\nセクシー美少女で", "玉泉美咲", 1050, 0, "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 0, 2, 0, 0, "アタシは玉泉美咲。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.4, "？？？？", "リマ", 1052, 0, "？？？？", 0, 2, 0, 0, "？？？", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", "モニカ・ヴァイスヴィント", 1053, 0, "そ、そこまでいうなら\nもらってやる", 0, 2, 0, 0, "モニカ・ヴァイスヴィントだ。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", "ペコリーヌ", 1058, 0, "そ、そこまでいうなら\nもらってやる", 0, 2, 0, 0, "モニカ・ヴァイスヴィントだ。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", "コッコロ", 1059, 0, "そ、そこまでいうなら\nもらってやる", 0, 2, 0, 0, "モニカ・ヴァイスヴィントだ。", 1, 1);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES (1, 0, 1.5, "菓子でつろうなどと\n稚拙な策を……", "キャル", 1060, 0, "そ、そこまでいうなら\nもらってやる", 0, 2, 0, 0, "モニカ・ヴァイスヴィントだ。", 1, 1);
